#include "physics/CCPhysicsHelper.h"
#if CC_USE_PHYSICS

#include <cmath>
#include <cstring>
#include <algorithm>
#include <vector>

NS_CC_BEGIN

Vec2 PhysicsHelper::cpv2point(const cpVect& v)
{
    return Vec2((float)v.x, (float)v.y);
}

cpVect PhysicsHelper::point2cpv(const Vec2& p)
{
    return cpv(p.x, p.y);
}

Size PhysicsHelper::cpv2size(const cpVect& v)
{
    return Size((float)v.x, (float)v.y);
}

cpVect PhysicsHelper::size2cpv(const Size& s)
{
    return cpv(s.width, s.height);
}

Rect PhysicsHelper::cpbb2rect(const cpBB& bb)
{
    return Rect((float)bb.l, (float)bb.b, (float)(bb.r - bb.l), (float)(bb.t - bb.b));
}

cpBB PhysicsHelper::rect2cpbb(const Rect& r)
{
    return cpBBNew((cpFloat)r.origin.x,
                   (cpFloat)r.origin.y,
                   (cpFloat)(r.origin.x + r.size.width),
                   (cpFloat)(r.origin.y + r.size.height));
}

float PhysicsHelper::cpfloat2float(cpFloat f)
{
    return (float)f;
}

void PhysicsHelper::points2cpvs(const Vec2* points, cpVect* outVerts, int count)
{
    if (points == nullptr || outVerts == nullptr || count <= 0)
    {
        return;
    }

    for (int i = 0; i < count; ++i)
    {
        outVerts[i] = point2cpv(points[i]);
    }
}

void PhysicsHelper::cpvs2points(const cpVect* verts, Vec2* outPoints, int count)
{
    if (verts == nullptr || outPoints == nullptr || count <= 0)
    {
        return;
    }

    for (int i = 0; i < count; ++i)
    {
        outPoints[i] = cpv2point(verts[i]);
    }
}

Vec2 PhysicsHelper::getBodyPosition(cpBody* body)
{
    return body == nullptr ? Vec2::ZERO : cpv2point(cpBodyGetPosition(body));
}

float PhysicsHelper::getBodyAngle(cpBody* body)
{
    return body == nullptr ? 0.0f : (float)cpBodyGetAngle(body);
}

cpTransform PhysicsHelper::transform2cpTransform(const Vec2& pos, float angle)
{
    cpFloat cosv = (cpFloat)std::cos(angle);
    cpFloat sinv = (cpFloat)std::sin(angle);

    // rigid transform: rotation by 'angle' followed by translation to 'pos'
    // cpTransform fields are { a, b, c, d, tx, ty } mapping (x, y) to
    // (a*x + c*y + tx, b*x + d*y + ty).
    cpTransform transform = {cosv, sinv, -sinv, cosv, (cpFloat)pos.x, (cpFloat)pos.y};
    return transform;
}

int PhysicsHelper::computeConvexHull(const Vec2* points, int count, Vec2* outHull)
{
    if (points == nullptr || outHull == nullptr || count <= 0)
    {
        return 0;
    }

    if (count == 1)
    {
        outHull[0] = points[0];
        return 1;
    }

    // Andrew's monotone chain algorithm.
    std::vector<Vec2> sorted(points, points + count);
    std::sort(sorted.begin(), sorted.end(), [](const Vec2& a, const Vec2& b) {
        return a.x < b.x || (a.x == b.x && a.y < b.y);
    });

    auto cross = [](const Vec2& o, const Vec2& a, const Vec2& b) -> float {
        return (a.x - o.x) * (b.y - o.y) - (a.y - o.y) * (b.x - o.x);
    };

    // the hull may temporarily hold count + 1 points (the first point is
    // repeated at the end), so build it in a scratch buffer first.
    std::vector<Vec2> hull(2 * count);
    int k = 0;

    // lower hull
    for (int i = 0; i < count; ++i)
    {
        while (k >= 2 && cross(hull[k - 2], hull[k - 1], sorted[i]) <= 0)
        {
            --k;
        }
        hull[k++] = sorted[i];
    }

    // upper hull
    for (int i = count - 2, t = k + 1; i >= 0; --i)
    {
        while (k >= t && cross(hull[k - 2], hull[k - 1], sorted[i]) <= 0)
        {
            --k;
        }
        hull[k++] = sorted[i];
    }

    // drop the duplicated start point
    int hullCount = k > 1 ? k - 1 : k;
    std::memcpy(outHull, hull.data(), hullCount * sizeof(Vec2));
    return hullCount;
}

Vec2 PhysicsHelper::computePolygonCenter(const Vec2* verts, int count)
{
    if (verts == nullptr || count <= 0)
    {
        return Vec2::ZERO;
    }

    std::vector<cpVect> cpvs(count);
    points2cpvs(verts, cpvs.data(), count);
    return cpv2point(cpCentroidForPoly(count, cpvs.data()));
}

bool PhysicsHelper::isPolygonConvex(const Vec2* verts, int count)
{
    if (verts == nullptr || count < 3)
    {
        return false;
    }

    // a polygon is convex if every consecutive edge cross product has the
    // same sign (zero crosses are allowed for collinear edges).
    float sign = 0.0f;
    for (int i = 0; i < count; ++i)
    {
        const Vec2& a = verts[i];
        const Vec2& b = verts[(i + 1) % count];
        const Vec2& c = verts[(i + 2) % count];
        float cross = (b.x - a.x) * (c.y - b.y) - (b.y - a.y) * (c.x - b.x);
        if (cross != 0.0f)
        {
            if (sign != 0.0f && cross * sign < 0.0f)
            {
                return false;
            }
            sign = cross;
        }
    }

    return true;
}

bool PhysicsHelper::segmentIntersect(const Vec2& a1, const Vec2& a2, const Vec2& b1, const Vec2& b2, Vec2* intersection)
{
    Vec2 d1 = a2 - a1;
    Vec2 d2 = b2 - b1;

    float denom = d1.x * d2.y - d1.y * d2.x;
    if (denom == 0.0f)
    {
        // parallel or collinear segments: no single intersection point
        return false;
    }

    Vec2 d = b1 - a1;
    float t = (d.x * d2.y - d.y * d2.x) / denom;
    float u = (d.x * d1.y - d.y * d1.x) / denom;

    if (t < 0.0f || t > 1.0f || u < 0.0f || u > 1.0f)
    {
        return false;
    }

    if (intersection != nullptr)
    {
        *intersection = a1 + d1 * t;
    }

    return true;
}

float PhysicsHelper::pointToSegmentDistance(const Vec2& point, const Vec2& segA, const Vec2& segB)
{
    Vec2 ab = segB - segA;
    float lengthSq = ab.x * ab.x + ab.y * ab.y;

    if (lengthSq == 0.0f)
    {
        // degenerate segment: distance to the single endpoint
        return point.getDistance(segA);
    }

    // project point onto the segment, clamped to [0, 1]
    Vec2 ap = point - segA;
    float t = (ap.x * ab.x + ap.y * ab.y) / lengthSq;
    t = clampf(t, 0.0f, 1.0f);

    Vec2 closest = segA + ab * t;
    return point.getDistance(closest);
}

float PhysicsHelper::polygonArea(const Vec2* verts, int count)
{
    if (verts == nullptr || count < 3)
    {
        return 0.0f;
    }

    std::vector<cpVect> cpvs(count);
    points2cpvs(verts, cpvs.data(), count);
    return std::fabs(cpfloat2float(cpAreaForPoly(count, cpvs.data(), 0.0f)));
}

float PhysicsHelper::polygonMoment(float mass, const Vec2* verts, int count, const Vec2& offset)
{
    if (verts == nullptr || count < 3)
    {
        return 0.0f;
    }

    std::vector<cpVect> cpvs(count);
    points2cpvs(verts, cpvs.data(), count);
    return cpfloat2float(cpMomentForPoly((cpFloat)mass, count, cpvs.data(), point2cpv(offset), 0.0f));
}

float PhysicsHelper::circleArea(float radius)
{
    return cpfloat2float(cpAreaForCircle(0.0f, (cpFloat)radius));
}

float PhysicsHelper::circleMoment(float mass, float radius, const Vec2& offset)
{
    return cpfloat2float(cpMomentForCircle((cpFloat)mass, 0.0f, (cpFloat)radius, point2cpv(offset)));
}

